(()=>{
  'use strict';
  window.SERAG_ENGLISH_FREE_ONLY=true;
  const $=(s,r=document)=>r.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const day=()=>new Date().toLocaleDateString('en-CA'),uid=()=>window.user?.id?window.user.id:'guest';
  const key=()=>`seragAcademyV12:${uid()}`;
  let owner='',state,tab='today',map='tenses',session=null,selected=null,root;
  const fresh=()=>({goal:'work',mode:8,attempts:[],cards:{},notes:{},sessions:[],scenario:null,practiceTopic:'be-basics',writingDrill:'paragraph',writingChecks:{},level:'B1',levelPart:'grammar',examTheme:'digital'});
  function load(){owner=uid();try{state={...fresh(),...JSON.parse(localStorage.getItem(key())||'{}')}}catch{state=fresh()}session=null}
  function save(){try{localStorage.setItem(key(),JSON.stringify(state))}catch{}}
  const extraLesson={id:'past-perfect-continuous',level:'B1',title:'Past Perfect Continuous',titleAr:'Past Perfect Continuous',summary:'An activity that started before a past point, with emphasis on its duration or effect at that point.',formula:'had been + verb-ing',examples:['I had been editing for two hours when the client called.','She was tired because she had been working all night.','By nine, we had been waiting for an hour.'],mistake:'With stative verbs such as know, use had known, not had been knowing.',tip:'Identify the past reference point, then ask how long the activity had continued before it.',quiz:['By noon, I ___ for three hours.','had been working','have been working'],task:'Describe an activity that continued for a period before another past event.'};
  const lessons=()=>[...(window.SERAG_GRAMMAR_V10||[]),extraLesson];
  const lesson=id=>lessons().find(x=>x.id===({'zero-first':'zero-first-conditionals','if-alternatives':'condition-linkers'}[id]||id));
  const maps={
    tenses:{name:'Tense map',root:'Choose the tense based on the meaning, not just a time expression.',branches:[
      ['Present',[['present-simple','Habit or fact','I work in marketing.'],['present-continuous','Now, a temporary situation or a fixed arrangement','I am editing a video now.'],['present-perfect','Experience or a result connected to the present','I have sent the file.'],['present-perfect-continuous','An activity continuing up to now','I have been working for two hours.']]],
      ['Past',[['past-simple','A completed past event','I sent it yesterday.'],['past-continuous','An action in progress in the past','I was editing when he called.'],['past-perfect','An event before another past event','I had finished before he arrived.'],['past-perfect-continuous','An activity duration before a past point','I had been working for hours.']]],
      ['Future',[['future-forms','will: a decision made now or a promise','I will help you.'],['future-forms','going to: an intention or prediction based on evidence','I am going to update my CV.'],['future-forms','Present Continuous: a fixed arrangement','I am meeting the client tomorrow.']]]],tip:'Tenses show how you view an event. More than one tense may be possible, but the meaning and emphasis change.'},
    basics:{name:'Grammar foundations',root:'Start with the noun, then identify description, quantity and place.',branches:[
      ['Nouns',[['articles','Indefinite singular: a/an; specific: the','an hour / a university / the report'],['countable','Countable or uncountable?','many tasks / much time'],['singular-plural-nouns','Choose a singular or plural verb','The news is good.']]],
      ['Description',[['adjective-adverb','An adjective describes a noun; an adverb modifies a verb.','a clear idea / explain clearly'],['ed-ing-adjectives','The feeling or the cause of the feeling?','I am bored. / The meeting is boring.'],['comparatives','A comparison or the superlative?','better than / the best']]],
      ['Prepositions',[['time-prepositions','Time: at a point, on a day, in a period','at 3 / on Monday / in May'],['place-prepositions','Place: at a point, on a surface, in an enclosed space','at work / on the desk / in a room'],['adjective-prepositions','Learn the full collocation','interested in / responsible for']]]],tip:'Choose a/an by sound, not spelling. Information and advice are usually uncountable.'},
    sentence:{name:'Sentence structure map',root:'Identify the tense and subject, choose the auxiliary, then build the sentence.',branches:[
      ['Questions',[['questions','With be, move the verb before the subject.','Are you ready?'],['questions','do/does/did + base verb','Where did you work?'],['questions','have/has/had + past participle','Have you sent the file?']]],
      ['Meaning',[['modals','Ability, advice, necessity or possibility','can / should / must / might + base'],['passive','Focus on the receiver of the action','The file was sent.'],['relative-clauses','Describe a person or thing','The designer who created it…']]],
      ['Verb patterns',[['gerund-infinitive','Verb + -ing or to + base verb','enjoy working / want to work'],['do-make','Activity or result? Learn the collocation.','do homework / make a decision'],['reported-speech','Report what someone said','He said he was busy.']]]],tip:'After does, did or a modal, use the base verb. Be + -ing and have + past participle follow different patterns.'},
    conditionals:{name:'Conditionals map',root:'Is it a fact, a real possibility, an imaginary situation, or a past regret?',branches:[
      ['Facts & possibility',[['zero-first','Zero: a general truth','If + present, present'],['zero-first','First: a real future possibility','If + present, will + base']]],
      ['Imaginary & regret',[['second-conditional','Second: an imaginary present or future','If + past, would + base'],['third-conditional','Third: an unreal past situation','If + had V3, would have V3']]],
      ['Mixed & alternatives',[['mixed-conditionals','A past cause with a present result','If I had studied, I would be ready.'],['if-alternatives','unless = if not; as long as = provided that','Unless you hurry, you will be late.']]]],tip:'Start with the foundations map if you have not studied conditionals yet. This section is separate and is not included in the default practice session unless you choose it.'}
  };
  Object.assign(maps,window.SERAG_SUPPLEMENT_V13?.maps||{});
  const scenarios=[
    ['Introduce yourself','Introduce yourself, your experience and your goal in 60 seconds.','I work as… / I have experience in…','present-simple'],
    ['Explain a design','Explain a design concept and why you chose its colors.','The main idea is… / I chose… because…','past-simple'],
    ['Client clarification','Ask the client three questions about the goal, dimensions and deadline.','Could you clarify…? / What is the deadline?','questions'],
    ['Project update','Explain what you have completed and what you are working on.','I have completed… / I am currently working on…','present-perfect'],
    ['Deadline negotiation','Suggest a realistic deadline and explain why.','Could we extend…? / I would need…','modals'],
    ['Tell a work story','Describe a problem and what you were doing when it happened.','I was… when… / After that…','past-continuous'],
    ['Interview achievement','Describe an achievement, your role and the result.','My role was… / The result was…','past-simple'],
    ['Portfolio pitch','Present a portfolio project in one minute.','The brief was… / I developed…','past-simple'],
    ['Meeting small talk','Start a conversation and ask a follow-up question.','How has your week been? / What are you working on?','questions'],
    ['Airport conversation','Explain the purpose and length of your trip and where you are staying.','I am visiting… / I will stay for…','future-forms'],
    ['Renting a room','Ask about rent, bills and transport.','Does the rent include…? / How far is…?','questions'],
    ['Australia interview','Explain why you want the role and what you can contribute.','I am interested in this role because…','adjective-prepositions'],
    ['Campaign results','Compare the results of two campaigns.','This campaign performed better than…','comparatives'],
    ['Ask for assets','Request the required assets and explain what is missing.','Could you send…? / I still need…','modals'],
    ['Give feedback','Make a suggestion without sounding confrontational.','It might be clearer if… / Could we try…?','modals'],
    ['Customer support','Explain the issue, when it started and what you have tried.','It stopped working… / I have tried…','present-perfect'],
    ['Daily routine','Describe your usual workday and how today is different.','I usually… / Today I am…','present-continuous'],
    ['Future plans','Talk about your learning plan and a confirmed arrangement for the week.','I am going to… / I am meeting…','future-forms'],
    ['Explain a process','Explain the stages of video production through delivery.','First… / Then… / Finally…','present-simple'],
    ['Handle misunderstanding','Politely correct a misunderstanding and restate your point simply.','What I meant was… / Let me clarify…','questions']
  ];
  scenarios.push(...(window.SERAG_ENGLISH_V9?.workPractice?.scenarios||[]).map(s=>[s.title,s.hint,s.starter,s.topic||'questions',s.prompt]));
  const extra=[
    {id:'past-duration',topic:'past-perfect-continuous',prompt:'He was tired because he ___ for three hours before the meeting.',options:['had been working','has been working','is working'],answer:'had been working',explanation:'Use had been + -ing for an activity that continued up to a past reference point.'},
    {id:'perfect-past',topic:'present-perfect',prompt:'I ___ the final design yesterday.',options:['sent','have sent','had been sending'],answer:'sent',explanation:'Yesterday refers to a finished past time, so use the Past Simple.'},
    {id:'did-base',topic:'questions',prompt:'Which question is correct?',options:['Did you send the file?','Did you sent the file?','Did you sending the file?'],answer:'Did you send the file?',explanation:'Use the base form send after did.'},
    {id:'phrase-align',topic:'adjective-prepositions',prompt:'The design should align ___ the brand guidelines.',options:['with','at','of'],answer:'with',explanation:'The full collocation is align with.'}
  ];
  function exampleQuestions(g){
    const answer=String(g.quiz?.[1]||'').trim(),wrong=String(g.quiz?.[2]||'').trim();
    if(!answer||!wrong)return [];
    return (g.examples||[]).flatMap((sentence,index)=>{
      const at=sentence.toLowerCase().indexOf(answer.toLowerCase());
      if(at<0)return [];
      const before=sentence[at-1]||' ',after=sentence[at+answer.length]||' ';
      if(/[A-Za-z]/.test(before)||/[A-Za-z]/.test(after))return [];
      const matched=sentence.slice(at,at+answer.length);
      const prompt=sentence.slice(0,at)+'___'+sentence.slice(at+answer.length);
      if(!prompt.includes('___')||prompt===g.quiz[0])return [];
      return [{id:'example:'+g.id+':'+index,topic:g.id,level:g.level,prompt,answer:matched,options:[matched,wrong],explanation:g.summary+' '+g.mistake,sourceExample:sentence}];
    });
  }
  function curriculumExampleQuestions(){
    const bank=window.SERAG_GRAMMAR_EXAMPLES_V1;
    if(typeof bank?.getExamples!=='function'||typeof bank?.getLessons!=='function')return [];
    const byId=new Map(bank.getLessons().map(lesson=>[String(lesson.id),lesson]));
    return bank.getExamples().flatMap(row=>{
      const lesson=byId.get(String(row.lessonId));
      const answer=String(lesson?.quiz?.[1]||'').trim();
      const wrong=String(lesson?.quiz?.[2]||'').trim();
      const sentence=String(row.sentence||'');
      if(!answer||!wrong||!sentence)return [];
      const at=sentence.toLowerCase().indexOf(answer.toLowerCase());
      if(at<0)return [];
      const before=sentence[at-1]||' ',after=sentence[at+answer.length]||' ';
      if(/[A-Za-z]/.test(before)||/[A-Za-z]/.test(after))return [];
      const matched=sentence.slice(at,at+answer.length);
      const prompt=sentence.slice(0,at)+'___'+sentence.slice(at+answer.length);
      if(!prompt.includes('___'))return [];
      return [{
        id:'curriculum-example:'+row.id,
        topic:String(row.lessonId),
        level:String(row.level||lesson.level||'B1'),
        prompt,
        answer:matched,
        options:[matched,wrong],
        explanation:[row.summary,lesson.mistake].filter(Boolean).join(' '),
        sourceExample:sentence,
        source:'curriculum-example'
      }];
    });
  }
  function questions(){
    const extraIds=new Set([...(window.SERAG_SUPPLEMENT_V13?.lessons||[]),...(window.SERAG_LEVELS_V14?.lessons||[]),...(window.SERAG_C1_ADVANCED_V1?.lessons||[])].map(g=>g.id));
    const baseLessons=lessons().filter(g=>!extraIds.has(g.id));
    const a=baseLessons.flatMap(g=>[{id:'lesson:'+g.id,topic:g.id,level:g.level,prompt:g.quiz[0],answer:g.quiz[1],options:[g.quiz[1],g.quiz[2]],explanation:g.summary+' '+g.mistake},...exampleQuestions(g)]);
    const b=(window.SERAG_REVIEW_V10_DATA?.questions||[]).filter(q=>q.type==='choice').map(q=>({...q,id:'review:'+q.n,topic:topicId(q.section)}));
    const generatedExamples=curriculumExampleQuestions();
    const all=[...a,...b,...extra,...generatedExamples,...(window.SERAG_SUPPLEMENT_V13?.questions||[]),...(window.SERAG_LEVELS_V14?.questions||[]),...(window.SERAG_CONTEXT_V15?.questions||[]),...(window.SERAG_PHRASES_V16?.questions||[]),...(window.SERAG_C1_ADVANCED_V1?.questions||[])];
    const ids=new Set(),prompts=new Set();
    return all.filter(q=>{
      if(!q||!q.id||!String(q.prompt||'').trim()||!Array.isArray(q.options)||!q.options.includes(q.answer))return false;
      const id=String(q.id),promptKey=String(q.topic||'')+'|'+String(q.prompt).toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim()+'|'+String(q.answer).toLowerCase();
      if(ids.has(id)||prompts.has(promptKey))return false;
      ids.add(id);prompts.add(promptKey);return true;
    });
  }
  function questionHistory(){
    const lastSeen=new Map();
    for(const attempt of state?.attempts||[]){if(attempt.id)lastSeen.set(attempt.id,Math.max(lastSeen.get(attempt.id)||0,Number(attempt.at)||0))}
    let remote={};try{remote=window.ENGOPLAY?.stats?.()||{}}catch{}
    const answered=remote.answeredKeys instanceof Set?remote.answeredKeys:new Set(remote.answeredKeys||[]);
    const remoteLast=remote.lastAnsweredAt;
    const lastAt=id=>Math.max(lastSeen.get(id)||0,remoteLast instanceof Map?Number(remoteLast.get(id))||0:Number(remoteLast?.[id])||0);
    const recentIds=new Set((state?.attempts||[]).slice(-10).map(attempt=>String(attempt.id||'')).filter(Boolean));
    const remoteRecent=remoteLast instanceof Map?[...remoteLast.entries()]:Object.entries(remoteLast||{});
    remoteRecent.sort((a,b)=>(Number(b[1])||0)-(Number(a[1])||0)).slice(0,10).forEach(([id])=>recentIds.add(String(id)));
    const stats=new Map();
    const remoteQuestionStats=remote.questionStats instanceof Map?remote.questionStats:new Map(Object.entries(remote.questionStats||{}));
    // Synced history is the cross-device source of truth; local attempts fill gaps while sync is pending.
    for(const [id,value] of remoteQuestionStats){
      stats.set(String(id),{total:Number(value?.total)||0,wrong:Number(value?.wrong)||0});
    }
    for(const attempt of (state?.attempts||[]).slice(-100)){
      if(!attempt.id||stats.has(String(attempt.id)))continue;
      const row=stats.get(String(attempt.id))||{total:0,wrong:0};
      row.total++;if(!attempt.correct)row.wrong++;
      stats.set(String(attempt.id),row);
    }
    const errorRate=id=>{const row=stats.get(String(id));return row?.total?row.wrong/row.total:0};
    return {lastSeen,answered,lastAt,recentIds,errorRate,cards:state?.cards||{},salt:String((state?.attempts||[]).length)+(state?.sessions||[]).length};
  }
  function practicePool(list,now=Date.now()){
    const history=questionHistory(),fresh=[],due=[],cooldown=[];
    for(const q of list){
      if(!q?.id)continue;
      const card=history.cards[q.id],last=history.lastAt(q.id),seen=!!card||history.lastSeen.has(q.id)||history.answered.has(q.id);
      const isDue=(card&&Number(card.due)<=now)||(!card&&last&&now-last>=86400000);
      // Keep recent due questions as a fallback, but never use a future-scheduled card early.
      if(history.recentIds.has(String(q.id))){if(!card||isDue)cooldown.push(q);continue}
      if(!seen){fresh.push(q);continue}
      if(isDue)due.push(q);
    }
    const orderedDue=due.sort((a,b)=>history.lastAt(a.id)-history.lastAt(b.id)||hash(a.id+history.salt)-hash(b.id+history.salt));
    // Due reviews first, then unseen material. Cooldown questions are a last-resort fallback.
    return [...orderedDue,...fresh,...(orderedDue.length||fresh.length?[]:cooldown)];
  }
  function selectQuestions(list,kind='daily',limit=state?.mode||8){
    const history=questionHistory(),now=Date.now();
    const candidates=kind==='review'?list:practicePool(list,now);
    const priority=q=>(history.cards[q.id]&&Number(history.cards[q.id].due)<=now)||(!history.cards[q.id]&&history.lastAt(q.id)&&now-history.lastAt(q.id)>=86400000)?0:1;
    const ordered=[...candidates].sort((a,b)=>priority(a)-priority(b)||history.errorRate(b.id)-history.errorRate(a.id)||(history.lastSeen.get(a.id)||0)-(history.lastSeen.get(b.id)||0)||hash(a.id+history.salt)-hash(b.id+history.salt));
    if(kind!=='daily')return ordered.slice(0,limit);
    const rankGroups=new Map();
    for(const q of ordered){const r=priority(q);if(!rankGroups.has(r))rankGroups.set(r,new Map());const groups=rankGroups.get(r),topic=q.topic||'mixed';if(!groups.has(topic))groups.set(topic,[]);groups.get(topic).push(q)}
    const diverse=[];
    for(const groups of rankGroups.values()){
      while([...groups.values()].some(rows=>rows.length)){
        for(const rows of groups.values())if(rows.length)diverse.push(rows.shift());
      }
    }
    return diverse.slice(0,limit);
  }
  function topicId(s){const t=String(s).toLowerCase();return lessons().find(g=>t.includes(g.title.toLowerCase()))?.id||({'a / an / the':'articles','in / on / at':'time-prepositions','much / many / a little / a few':'countable','mixed tenses':'past-simple'})[t]||'questions'}
  function record(q,answer){const correct=answer===q.answer;if(window.EngoRotation&&String(q.id||'').startsWith('engoplay-grammar-batch-q'))window.EngoRotation.recordAnswer(q.id,correct);state.attempts.push({id:q.id,topic:q.topic,correct,answer,date:day(),at:Date.now()});state.attempts=state.attempts.slice(-1000);const old=state.cards[q.id]||{stage:0};const stage=correct?Math.min((old.stage||0)+1,5):0;state.cards[q.id]={stage,due:Date.now()+[0,1,3,7,14,30][stage]*86400000,wrong:correct?!!old.wrong:true};save();window.ENGOPLAY?.track(state.attempts.at(-1))}
  function due(){return questions().filter(q=>state.cards[q.id]&&state.cards[q.id].due<=Date.now())}
  function weak(){const groups={};state.attempts.forEach(a=>{groups[a.topic]??={wrong:0,total:0};groups[a.topic].total++;if(!a.correct)groups[a.topic].wrong++});return Object.entries(groups).filter(([,x])=>x.wrong).sort((a,b)=>b[1].wrong/b[1].total-a[1].wrong/a[1].total)}
  function start(kind='daily',topic=state.practiceTopic){
    stop();
    let list=questions();
    if(kind==='review')list=due();
    if(kind==='smart')list=questions();
    if(kind==='topic')list=list.filter(q=>q.topic===topic);
    if(kind==='quick')list=window.EngoRotation?window.EngoRotation.pickQuestions(list,{count:5}):selectQuestions(list,'daily',5);
    if(kind==='smart')list=window.EngoRotation?window.EngoRotation.pickQuestions(list,{count:10,mode:'review'}):due();
    if(kind==='hardest')list=window.EngoRotation?window.EngoRotation.pickQuestions(list,{count:10,mode:'hardest'}):selectQuestions(list,'daily',10);
    if(kind==='phrases')list=window.SERAG_PHRASES_V16?.questions||[];
    if(kind==='level')list=list.filter(q=>(q.level||lesson(q.topic)?.level)===state.level);
    if(kind==='context'||kind==='exam')list=(window.SERAG_CONTEXT_V15?.questions||[]).filter(q=>q.level===state.level&&(kind==='exam'||q.theme===state.examTheme));
    if(kind==='context'||kind==='exam'){const eligible=list.filter(q=>!state.cards[q.id]||state.cards[q.id].due<=Date.now());if(eligible.length&&kind==='context')list=eligible;list.sort((a,b)=>hash(a.id+String(state.attempts.length))-hash(b.id+String(state.attempts.length)));}
    if(kind==='placement')list=questions().filter(q=>q.id.startsWith('lesson:')).slice(0,18);
    if(kind==='daily')list=list.filter(q=>!['zero-first-conditionals','second-conditional','third-conditional','mixed-conditionals','condition-linkers'].includes(q.topic));
    if(kind==='daily'||kind==='topic'||kind==='level'){
      const eligible=list.filter(q=>!state.cards[q.id]||state.cards[q.id].due<=Date.now());
      if(eligible.length)list=eligible;
      const priorities=weak().map(([id])=>id);
      list.sort((a,b)=>{const pa=priorities.indexOf(a.topic),pb=priorities.indexOf(b.topic);return (pa<0?999:pa)-(pb<0?999:pb)});
      // Level practice uses the same fresh/due filtering and topic interleaving as daily practice.
      if(kind==='topic'&&window.EngoRotation&&String(topic).startsWith('grammar-batch-topic-')){
        const topicRows=lessons().filter(g=>g.id===topic).map(g=>({id:g.id,practice_questions:list}));
        list=window.EngoRotation.getSessionQuestions(topic,topicRows);
      }else list=selectQuestions(list,kind==='topic'?'topic':'daily',kind==='topic'?list.length:state.mode);
    }
    const limit=kind==='placement'?18:kind==='topic'||kind==='context'?list.length:kind==='exam'?12:kind==='quick'?5:kind==='smart'||kind==='hardest'?10:state.mode;
    session={kind,list:list.slice(0,limit),index:0,score:0,answered:false,answers:{},completed:false};tab='today';render();$('.ea14-questions',root)?.scrollIntoView({block:'nearest',behavior:'smooth'});
  }
  function restoreAnswer(){const a=session.answers[session.index];session.answered=!!a;session.answer=a?.answer;selected=null}
  function hash(s){return [...s].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0)}
  function buttons(){return `<div class="ea12-actions"><button class="ea12-btn primary" data-ea-start="daily">Start grammar practice</button><button class="ea12-btn" data-ea-start="review">Review due (${due().length})</button><button class="ea12-btn" data-ea-start="placement">Grammar level check</button></div>`}
  function todayHTML(){return `<div class="ea14-question-head"><div><small>START HERE · Question hub</small><h3>Choose a practice mode and start with one question</h3><p>All grammar questions in one place, with feedback and answer history.</p></div><span class="ea14-count">${questions().length}<small>questions</small></span></div>${session?sessionHTML():`<div class="ea14-training"><button class="ea14-start" data-ea-start="daily"><b>Mixed practice</b><span>${state.mode} questions · Unanswered and due questions first</span></button><button class="ea14-start" data-ea-start="level"><b>${state.level} practice</b><span>Questions from the selected level</span></button><button class="ea14-start" data-ea-start="review"><b>Review mistakes</b><span>${due().length} questions due</span></button><button class="ea14-start" data-ea-start="quick"><b>Quick quiz · 5 minutes</b><span>5 mixed grammar questions</span></button><button class="ea14-start" data-ea-start="smart"><b>Smart review</b><span>Up to 10 questions due now</span></button><button class="ea14-start" data-ea-start="hardest"><b>Hardest challenge</b><span>Your highest error-rate questions</span></button><button class="ea12-btn" data-ea-new-session>Try a new session</button></div><div class="ea14-controls"><label>Level <select data-ea-level>${['B1','B2','C1','C2'].map(l=>`<option ${state.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Session size <select data-ea-mode>${[5,8,12].map(n=>`<option value="${n}" ${state.mode===n?'selected':''}>${n} questions</option>`).join('')}</select></label><button class="ea12-btn" data-ea-tab="bank">Choose a specific topic</button><button class="ea12-btn" data-ea-tab="history">Answer history</button></div>`}`}
  function levelsHTML(){const current=state.level||'B1',desc={B1:'Use grammar confidently in everyday situations.',B2:'Explain opinions and discuss possibilities.',C1:'Express ideas precisely and connect arguments.',C2:'Use precise and flexible language.'},list=window.EngoRotation?window.EngoRotation.pickTopics(lessons().filter(g=>g.level===current)):lessons().filter(g=>g.level===current),part=state.levelPart||'grammar',themes=window.SERAG_CONTEXT_V15?.themes||[];return `<div class="ea14-level-tabs">${Object.keys(desc).map(l=>`<button data-ea-level-pick="${l}" aria-pressed="${current===l}"><b>${l}</b><span>${desc[l]}</span></button>`).join('')}</div><div class="ea14-section-head"><div><h3>${current} learning path</h3><p>Review grammar, then apply it to a different topic. This is a practice path, not a CEFR certification.</p></div></div><nav class="ea15-parts" aria-label="Level sections"><button data-ea-level-part="grammar" aria-pressed="${part==='grammar'}"><b>01 · Grammar</b><span>${list.length} lessons · Explanations and examples</span></button><button data-ea-level-part="exams" aria-pressed="${part==='exams'}"><b>02 · Questions & exams</b><span>8 topics · Contextual practice and mixed exams</span></button></nav>${part==='grammar'?`<div class="ea14-lesson-grid">${list.map((g,i)=>`<button class="ea12-node" data-ea-lesson="${g.id}"><small>Lesson ${i+1} · ${g.level}</small><b>${esc(g.title)}</b><span class="ea12-en">${esc(g.title)}</span></button>`).join('')}</div><details class="ea14-foundation"><summary>Review the foundations? A1 / A2</summary><div class="ea14-lesson-grid">${lessons().filter(g=>['A1','A2'].includes(g.level)).map(g=>`<button class="ea12-node" data-ea-lesson="${g.id}"><b>${esc(g.title)}</b><small>${g.level} · ${esc(g.title)}</small></button>`).join('')}</div></details>`:`<div class="ea15-exam-hero"><div><small>LEVEL ${current} · MIXED CHALLENGE</small><h3>Real-life exam</h3><p>12 questions across different topics, applying ${current} grammar in context. Review feedback after each answer and see your score at the end.</p></div><button class="ea12-btn primary" data-ea-start="exam">Start exam</button></div><div class="ea14-lesson-grid">${themes.map(t=>`<article class="ea12-card"><small>${esc(t.title)}</small><h4>${esc(t.title)}</h4><p>${esc(t.description)}</p><small>3 questions · Level ${current}</small><button class="ea12-btn" data-ea-context="${t.id}">Practise this topic</button></article>`).join('')}</div><p>Original scenarios inspired by everyday life, not copied news. Unanswered questions appear first, and your answers remain in your review history.</p>`}`}
  function libraryHTML(){const libraryTopics=window.EngoRotation?window.EngoRotation.pickTopics(lessons()):lessons();return `<div class="ea14-section-head"><div><h3>Grammar library</h3><p>Search by topic or follow your level path.</p></div><button class="ea12-btn" data-ea-tab="levels">B1–C2 learning path</button></div><label class="ea14-search">Search grammar topics <input data-ea-search placeholder="e.g. conditionals, perfect tenses, negatives" value="${esc(state.lessonSearch||'')}"></label><div class="ea14-lesson-grid">${libraryTopics.filter(g=>[g.title,g.titleAr,g.summary].join(' ').toLowerCase().includes((state.lessonSearch||'').toLowerCase())).map(g=>`<button class="ea12-node" data-ea-lesson="${g.id}"><small>${g.level||'B1'}</small><b>${esc(g.title)}</b><span class="ea12-en">${esc(g.title)}</span></button>`).join('')||'<p>No results. Try another search.</p>'}</div>`}
  const sections=[['levels','01','B1–C2 learning path','Learn by level'],['grammar','02','Grammar','All lessons and search'],['examples','03','Grammar examples','Search examples by topic'],['maps','04','Grammar maps','Connect grammar topics'],['words','05','Vocabulary','Daily words and vocabulary bank'],['sentences','06','Sentence library','12,574 searchable sentence pairs'],['corrections','07','Mistake bank','Correct sentences and understand the reason'],['reading','08','Reading','Articles and reading comprehension'],['writing','09','Writing / IELTS','Writing practice and review'],['practice','10','Speaking & video','Practice and recording'],['progress','11','Progress & library','Results and saved items']];
  const sectionName=id=>sections.find(x=>x[0]===id)?.[2]||({bank:'Topic practice',history:'Answer history',mistakes:'Mistakes & review'})[id]||'';
  function sessionHTML(){
    if(!session.list.length)return '<p>No questions are due right now. Choose a topic from the question bank.</p><button class="ea12-btn" data-ea-end>Back</button>';
    if(session.index>=session.list.length)return `<h3>${session.kind==='exam'?'Exam complete':'Session complete'} ✓</h3><p class="ea12-kpi">${session.score}/${session.list.length}</p><p>You can review your answers without recording another attempt.</p><div class="ea12-actions"><button class="ea12-btn" data-ea-prev>← Previous question</button><button class="ea12-btn primary" data-ea-tab="mistakes">Review mistakes</button><button class="ea12-btn" data-ea-end>Finish</button></div>`;
    const q=session.list[session.index],options=q.options.slice().sort((a,b)=>hash(a+q.id+day())-hash(b+q.id+day()));
    return `<div class="ea12-actions"><small>${q.theme?esc(window.SERAG_CONTEXT_V15?.themes.find(t=>t.id===q.theme)?.title)+' · ':''}${esc(lesson(q.topic)?.title||'Practice')} · ${session.index+1}/${session.list.length}</small><button class="ea12-btn" data-ea-prev ${session.index===0?'disabled':''}>← Previous</button></div><div class="ea12-bar"><i style="width:${session.index/session.list.length*100}%"></i></div><h3 class="ea12-en">${esc(q.prompt)}</h3><div class="ea12-options">${options.map(x=>`<button data-ea-answer="${esc(x)}" ${session.answered?'disabled':''} class="${session.answered?(x===q.answer?'correct':x===session.answer?'wrong':''):''}">${esc(x)}</button>`).join('')}</div>${session.answered?`<div class="ea12-feedback-slot"><div class="ea12-tip" role="status"><b>${session.answer===q.answer?'Correct ✓':'Correct answer: '+esc(q.answer)}</b><p>${esc(q.explanation)}</p>${q.arabic_explanation?`<p class="ea12-arabic-explanation" dir="rtl" lang="ar">${esc(q.arabic_explanation)}</p>`:''}${q.topic==='natural-expressions'?'<button class="ea12-btn" data-ea-tab="words">Review expression</button>':`<button class="ea12-btn" data-ea-lesson="${esc(q.topic)}">Review grammar</button>`}</div></div><div class="ea12-next-slot"><div class="ea12-actions"><button class="ea12-btn primary" data-ea-next>Next question →</button></div></div>`:`<div class="ea12-feedback-slot"><div class="ea12-feedback-placeholder" aria-hidden="true"><div class="ea12-tip"><b>Answer feedback</b><p>Feedback will appear here after you answer.</p></div></div></div><div class="ea12-next-slot"><div class="ea12-actions"><button class="ea12-btn primary ea12-next-placeholder" disabled aria-hidden="true" tabindex="-1">Next question →</button></div></div>`}<p class="ea13-status">${session.answered?'Your answer is saved. Going back shows the original attempt and does not add another result.':'Choose an answer to see feedback, then continue.'}</p><button class="ea12-btn" data-ea-end>Exit and save answers</button>`;
  }
  function bankHTML(){const topic=state.practiceTopic||'be-basics';return `<h3>Question bank · One question at a time</h3><p>${questions().length} questions across different grammar topics. Unanswered and due questions appear first. Previous attempts remain in your review history.</p><div class="ea13-topic-toolbar"><label>Topic <select data-ea-topic>${lessons().map(g=>`<option value="${g.id}" ${topic===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><button class="ea12-btn primary" data-ea-start="topic">Start topic practice</button><button class="ea12-btn" data-ea-lesson="${topic}">Review first</button></div><h4>Suggested path</h4><div class="ea13-path">${[
    ['Sentence foundations','be-basics','Subject and verb → be → pronouns → possession → demonstratives'],
    ['Build stronger sentences','sentence-boundaries','Word order → adverbs of frequency → sentence links → cause and contrast'],
    ['Stronger writing','paraphrase-meaning','Preserve meaning → describe changes → write a clear paragraph → IELTS']
    ].map(([t,id,d])=>`<button class="ea12-node" data-ea-lesson="${id}"><b>${t}</b><small>${d}</small></button>`).join('')}</div><details><summary>Recent answers (${Math.min(state.attempts.length,30)})</summary>${state.attempts.slice(-30).reverse().map(a=>{const q=questions().find(q=>q.id===a.id);return q?`<article class="ea12-card"><p class="ea12-en">${esc(q.prompt)}</p><small>${a.correct?'✓ Correct':'Needs review'} · ${esc(a.date)}</small><p>Your answer: <span class="ea12-en">${esc(a.answer||'Not saved in the previous version')}</span></p><p>Correct answer: <span class="ea12-en">${esc(q.answer)}</span></p><p>${esc(q.explanation)}</p></article>`:''}).join('')||'<p>Complete a practice session to see your answer history here.</p>'}</details>`}
  function mapsHTML(){const m=maps[map];return `<div class="ea12-chips">${Object.entries(maps).map(([id,v])=>`<button data-ea-map="${id}" aria-pressed="${id===map}">${v.name}</button>`).join('')}</div><p>Each branch groups related grammar topics. Select a topic to view its form, examples and differences.</p><div class="ea12-map"><div class="ea12-root">${m.root}</div><div class="ea12-grid">${m.branches.map(([title,nodes])=>`<section class="ea12-card ea12-branch"><h4>${title}</h4>${nodes.map(([id,t,e])=>`<button class="ea12-node" data-ea-lesson="${id}"><b>${t}</b><small class="ea12-en">${esc(e)}</small></button>`).join('')}</section>`).join('')}</div></div><div class="ea12-tip">${m.tip}</div>${map==='tenses'?contrastHTML():''}`}
  function contrastHTML(){return `<h3 style="margin-top:22px">Same verb, different meaning</h3><div class="ea12-timeline"><span>Earlier past<br>had finished</span><span>Past point<br>arrived</span><span>Now<br>have finished</span><span>Future<br>will finish</span></div><div class="ea12-table"><table><thead><tr><th>Comparison</th><th>Example</th><th>Meaning</th></tr></thead><tbody>${[
    ['Simple / Continuous','I work here. / I am working here this week.','A stable state versus a temporary situation.'],['Past / Present Perfect','I sent it yesterday. / I have sent it.','A finished past time versus a present result.'],['Perfect / Perfect Continuous','I have edited three videos. / I have been editing for hours.','Quantity or result versus activity or duration.'],['Past Simple / Past Perfect','When I arrived, he left. / When I arrived, he had left.','He left when I arrived versus before I arrived.'],['Past Continuous / Past Perfect Continuous','I was working at nine. / I had been working for hours by nine.','An activity at a specific time versus its duration before that time.']].map(([a,b,c])=>`<tr><td>${a}</td><td class="ea12-en">${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div>`}
  function detailHTML(){const g=lesson(selected);if(!g)return '';return `<section class="ea12-modal"><div class="ea12-actions"><h3>${esc(g.title)} · ${esc(g.title)}</h3><button class="ea12-btn" data-ea-close>Close</button></div><p>${esc(g.summary)}</p>${g.arabic_explanation?`<p class="ea12-arabic-explanation" dir="rtl" lang="ar">${esc(g.arabic_explanation)}</p>`:''}<div class="ea12-formula">${esc(g.formula)}</div>${g.examples.map(x=>`<p class="ea12-en">${esc(x)}</p>`).join('')}<div class="ea12-tip">Note: ${esc(g.mistake)}<br>Remember: ${esc(g.tip)}</div><p>Apply: ${esc(g.task)}</p><button class="ea12-btn primary" data-ea-topic-start="${g.id}">More questions on this topic</button><textarea class="ea12-input" data-ea-note="${g.id}" placeholder="Write your own example — saved automatically">${esc(state.notes[g.id]||'')}</textarea><small>Your example is saved locally. Review it using the form and examples.</small></section>`}
  function mistakesHTML(){const list=questions().filter(q=>state.cards[q.id]?.wrong);return `<h3>Mistake bank & review</h3><p>Reviews are scheduled after 1, 3, 7, 14 or 30 days based on your performance. Incorrect answers return to the current review queue.</p><button class="ea12-btn primary" data-ea-start="review">Start due review (${due().length})</button><div class="ea12-grid" style="margin-top:16px">${list.length?list.map(q=>`<article class="ea12-card"><h4 class="ea12-en">${esc(q.prompt)}</h4><p class="ea12-en">${esc(q.answer)}</p><p>${esc(q.explanation)}</p><small>${state.cards[q.id].stage>=3?'Mastered':'Needs review'} · ${new Date(state.cards[q.id].due).toLocaleDateString('en-US')}</small><button class="ea12-btn" data-ea-lesson="${q.topic}">Grammar</button></article>`).join(''):'<p>No mistakes recorded yet. Complete a short session to get started.</p>'}</div>`}
  function practiceHTML(){let i=state.scenario;if(i==null){i=scenarios.findIndex(s=>s[0]==='Daily work briefing');if(i<0)i=state.goal==='australia'?11:state.goal==='travel'?9:0;}const s=scenarios[i]||scenarios[0];return `<h3>Scenario Studio · ${scenarios.length} scenarios</h3><p>Free self-guided practice. No AI chat or paid pronunciation scoring.</p><select data-ea-scenario>${scenarios.map((s,j)=>`<option value="${j}" ${j===i?'selected':''}>${s[0]}</option>`).join('')}</select><div class="ea12-tip"><h3>${s[0]}</h3><p>${s[1]}</p>${s[4] ? '<p class="ea12-en">' + esc(s[4]) + '</p>' : ''}<div class="ea12-en">${s[2]}</div></div><div class="ea12-actions"><button class="ea12-btn" data-ea-lesson="${s[3]}">Relevant grammar</button><button class="ea12-btn" data-ea-speak type="button">Listen to the prompt</button><button class="ea12-btn ea12-record-btn" data-ea-record type="button" aria-label="Record a spoken answer" title="Record a spoken answer" aria-pressed="false"><span class="ea12-record-icon" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4M8 22h8" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><span class="ea12-record-label">Record an attempt</span></button><button class="ea12-btn" data-ea-stop type="button" disabled>Stop recording</button></div><p id="ea12RecordStatus" role="status">Your recording stays on this device. You can listen and record again; it is not sent to an API.</p><audio id="ea12Audio" controls class="ea12-hidden"></audio><textarea class="ea12-input" data-ea-note="scenario:${i}" placeholder="Write your answer or notes…">${esc(state.notes['scenario:'+i]||'')}</textarea><div class="ea12-tip">Self-check: Did you meet the goal? Use the target grammar? Present your idea clearly? Record again after improving one thing.</div>`}
  function progressHTML(){const phraseState=window.SERAG_WORD_PRACTICE?.progress?.()||{},workPracticed=Object.values(phraseState).filter(x=>x.workRelated&&Date.parse(x.at||'')>Date.now()-7*86400000).length,week=state.attempts.filter(a=>a.at>Date.now()-7*86400000),correct=week.filter(a=>a.correct).length,mastered=Object.values(state.cards).filter(x=>x.stage>=3).length;return `<h3>Progress beyond XP</h3><div class="ea12-grid"><div class="ea12-card"><span class="ea12-kpi">${week.length}</span>Answers this week</div><div class="ea12-card"><span class="ea12-kpi">${week.length?Math.round(correct/week.length*100):0}%</span>Weekly accuracy</div><div class="ea12-card"><span class="ea12-kpi">${mastered}</span>Questions answered correctly 3 or more times</div></div><p class="ea12-tip">Work-related expressions practised in the last 7 days: ${workPracticed}. This counts distinct expressions you reviewed; it is not a language-level assessment.</p><h3 style="margin-top:20px">Grammar topics to review</h3><div class="ea12-summary">${weak().slice(0,5).map(([id,x])=>`<button class="ea12-node" data-ea-lesson="${id}"><b>${esc(lesson(id)?.title||id)}</b><small>${x.wrong} errors out of ${x.total} answers</small></button>`).join('')||'<p>Your report will appear after your first session.</p>'}</div><p>Local progress is stored separately for each account on this browser. These new statistics are not synced across devices yet; existing grammar progress is unchanged.</p>`}
  function render(){if(!root)return;window.SERAG_VIDEO_V17?.cleanup();if($('#page-english')&&!$('#page-english').classList.contains('hidden'))window.SERAG_HOME_V18?.syncNav(tab==='play'||tab==='mixed'||(tab==='today'&&session?.kind==='engoplay')?'engoplay':'english');if(root.classList){root.classList.toggle('ep-page',tab==='play');root.classList.toggle('ep-session',tab==='today'&&session?.kind==='engoplay');root.classList.toggle('ep-mixed-session',tab==='mixed')}if(tab==='mixed'&&window.SERAG_WORD_PRACTICE){root.innerHTML=`<header class="ea12-hero ea14-hero"><div><div class="ea12-eyebrow">ENGOPLAY · TODAY’S PRACTICE</div><h2>Today’s practice</h2><p>Vocabulary, grammar and sentence building in one session.</p></div><button class="ea12-btn" data-ea-tab="play">← EngoPlay</button></header><section id="ea14Content" class="ea12-panel"><div data-word-practice></div></section>`;organizeLegacy();return}if(tab==='play'&&window.ENGOPLAY){root.innerHTML=window.ENGOPLAY.renderLobby();organizeLegacy();return}if(tab==='today'&&session?.kind==='engoplay'){root.innerHTML=`<header class="ep-session-header"><button class="ep-text-button" data-ea-tab="play">← Engoplay</button><span>${esc(session.title)} · ${state.level}</span><button class="ep-streak-pill" data-ep-streak>🔥 ${window.ENGOPLAY.stats().current}</button></header><section class="ea12-panel ea14-questions" aria-label="EngoPlay challenge">${sessionHTML()}</section>${detailHTML()}`;organizeLegacy();return}const html=({levels:levelsHTML,grammar:libraryHTML,examples:()=>window.SERAG_GRAMMAR_EXAMPLES_V1?.html()||'<p>Loading grammar examples…</p>',maps:mapsHTML,mistakes:mistakesHTML,practice:()=>(window.SERAG_VIDEO_V17?.html(state)||'')+`<details class="ev17-import"><summary>Scenario practice without video</summary>${practiceHTML()}</details>`,progress:progressHTML,bank:bankHTML,history:bankHTML,sentences:()=>window.SERAG_TATOEBA_EXPLORER_V1?.html()||'<p>Loading the sentence library…</p>',corrections:()=>window.SERAG_MISTAKES_BANK_V1?.html()||'<p>Loading the mistake bank…</p>',writing:()=>window.SERAG_WRITING_V13?.html(state,esc)||'Loading…',words:()=>window.SERAG_PHRASES_V16?.html(esc)||'<p>Daily vocabulary and a topic-based word bank.</p>',reading:()=>window.SERAG_READING_STUDIO_V2?.summaryHTML()||window.SERAG_READING_LIBRARY_V1?.summaryHTML()||'<p>Read the article and review vocabulary in context.</p>'})[tab];root.innerHTML=`<header class="ea12-hero ea14-hero"><div><div class="ea12-eyebrow">SERAG ENGLISH</div><h2>One place. A clear next step.</h2><p>Start with questions or choose a skill to practise.</p></div>${window.ENGOPLAY?'<button class="ea12-btn" data-ea-tab="play">← Engoplay</button>':''}<button class="ea12-btn" data-ea-tab="levels">Your path: ${state.level||'B1'} ↗</button></header><section class="ea12-panel ea14-questions" aria-label="Question hub">${todayHTML()}</section><div class="ea14-section-head"><div><small>EXPLORE · SECTIONS</small><h3>What would you like to practise?</h3></div><button class="ea12-btn" data-ea-tab="today">Questions ↑</button></div><nav class="ea14-sections" aria-label="English sections">${sections.map(([id,n,t,d])=>`<button data-ea-tab="${id}" aria-pressed="${tab===id}" aria-controls="ea14Content"><small>${n}</small><b>${t}</b><span>${d}</span></button>`).join('')}</nav>${tab!=='today'?`<section id="ea14Content" class="ea12-panel"><div class="ea14-section-head"><h3>${sectionName(tab)}</h3><button class="ea12-btn" data-ea-tab="today">Close section</button></div>${html?html():''}</section>`:''}${detailHTML()}`;organizeLegacy();if(tab==='practice')window.SERAG_VIDEO_V17?.mount(root,state,save,render)}
  function organizeLegacy(){const hub=$('.el9-hub');if(!hub?.querySelectorAll)return;hub.classList.add('ea14-unified');const visible={bank:['seragReviewWrap'],words:['el9Words','el9Quiz','el9WordBankWrap'],reading:['el9Article'],practice:[],progress:['el9ArchiveWrap']};hub.querySelectorAll(':scope > :not(#ea12Center)').forEach(el=>{let show=false;for(const id of visible[tab]||[]){if(el.id===id||el.querySelector('#'+id)){show=true;const target=document.getElementById(id);if(target&&target.tagName==='DETAILS')target.open=true}}el.classList.toggle('ea14-legacy-hidden',!show);if(show)el.querySelectorAll(':scope > section').forEach(c=>c.classList.toggle('ea14-legacy-hidden',!(visible[tab]||[]).includes(c.id)))});const page=$('#page-english');if(page){page.classList.add('ea14-page');const personal=$('#el9PersonalLibrary');const review=$('#seragReviewWrap');if(review&&!hub.contains(review)){review.classList.toggle('ea14-legacy-hidden',tab!=='bank');review.open=tab==='bank'}if(personal){personal.classList.toggle('ea14-legacy-hidden',tab!=='progress');personal.open=tab==='progress'}}}
  let recorder=null,stream=null,audioUrl=null;
  function recordingUI(active){const recordBtn=$('[data-ea-record]',root),stopBtn=$('[data-ea-stop]',root),label=$('.ea12-record-label',root);if(recordBtn){recordBtn.disabled=active;recordBtn.classList.toggle('is-recording',active);recordBtn.setAttribute('aria-pressed',String(active));if(label)label.textContent=active?'Recording…':'Record an attempt'}if(stopBtn)stopBtn.disabled=!active}function stop(){const active=recorder?.state==='recording';if(active)recorder.stop();else{stream?.getTracks().forEach(t=>t.stop());stream=null}recordingUI(false)}
  async function recordAudio(){stop();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#ea12RecordStatus',root).textContent='Recording is not supported. Use your phone’s recorder or type your answer.';return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);const chunks=[];recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{recordingUI(false);stream?.getTracks().forEach(t=>t.stop());stream=null;if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));const player=$('#ea12Audio',root);if(player){player.src=audioUrl;player.classList.remove('ea12-hidden')}const status=$('#ea12RecordStatus',root);if(status)status.textContent='Listen to your recording, choose one thing to improve, and record again.'};recorder.start();recordingUI(true);$('#ea12RecordStatus',root).textContent='Recording… Select Stop recording when you are done.'}catch{stop();recordingUI(false);const status=$('#ea12RecordStatus',root);if(status)status.textContent='Microphone access was denied. Allow access in your browser or type your answer.'}}
  function mount(){const hub=$('.el9-hub');if(!hub)return false;if($('#ea12Center'))return true;load();root=document.createElement('section');root.id='ea12Center';root.className='ea12';hub.prepend(root);render();root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.eaLevelPart){state.levelPart=b.dataset.eaLevelPart;selected=null;save();render()}else if(b.dataset.eaContext){state.examTheme=b.dataset.eaContext;selected=null;save();start('context')}else if(b.dataset.eaLevelPick){state.level=b.dataset.eaLevelPick;save();render()}else if(b.dataset.eaTab){stop();tab=b.dataset.eaTab;selected=null;render();if(tab!=='today')$('#ea14Content',root)?.scrollIntoView({block:'nearest',behavior:'smooth'})}else if(b.dataset.eaMap){map=b.dataset.eaMap;selected=null;render()}else if(b.dataset.eaLesson){selected=b.dataset.eaLesson;render();$('.ea12-modal',root)?.scrollIntoView({block:'nearest',behavior:'smooth'})}else if(b.hasAttribute('data-ea-close')){selected=null;render()}else if(b.dataset.eaTopicStart){state.practiceTopic=b.dataset.eaTopicStart;selected=null;save();start('topic')}else if(b.dataset.eaStart){selected=null;start(b.dataset.eaStart)}else if(b.hasAttribute('data-ea-new-session')){window.EngoRotation?.newSessionSeed();session=null;render()}else if(b.hasAttribute('data-ea-answer')&&session&&!session.answered){const q=session.list[session.index];session.answered=true;session.answer=b.dataset.eaAnswer;session.answers[session.index]={answer:session.answer};record(q,session.answer);if(session.answer===q.answer)session.score++;render()}else if(b.hasAttribute('data-ea-prev')&&session&&session.index>0){session.index--;restoreAnswer();render()}else if(b.hasAttribute('data-ea-next')&&session?.answered){session.index++;restoreAnswer();if(session.index===session.list.length&&!session.completed){session.completed=true;state.sessions.push({date:day(),score:session.score,total:session.list.length});state.sessions=state.sessions.slice(-100);save()}render()}else if(b.hasAttribute('data-ea-end')){const backToPlay=session?.kind==='engoplay',backToLevel=['context','exam'].includes(session?.kind);session=null;selected=null;if(backToPlay)tab='play';if(backToLevel){tab='levels';state.levelPart='exams'}render()}else if(b.hasAttribute('data-ea-record'))void recordAudio();else if(b.hasAttribute('data-ea-stop'))stop();else if(b.hasAttribute('data-ea-speak')){const i=state.scenario?? (state.goal==='australia'?11:state.goal==='travel'?9:0);if(window.speechSynthesis){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(scenarios[i][2]);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}}});root.addEventListener('change',e=>{if(e.target.hasAttribute('data-ea-level')){state.level=e.target.value;render()}if(e.target.hasAttribute('data-ea-topic')){state.practiceTopic=e.target.value;render()}if(e.target.hasAttribute('data-ea-writing')){state.writingDrill=e.target.value;render()}if(e.target.hasAttribute('data-ea-writing-check')){state.writingChecks??={};state.writingChecks[e.target.dataset.eaWritingCheck]=e.target.checked}if(e.target.hasAttribute('data-ea-mode'))state.mode=Number(e.target.value);if(e.target.hasAttribute('data-ea-goal'))state.goal=e.target.value;if(e.target.hasAttribute('data-ea-scenario')){stop();state.scenario=Number(e.target.value);render()}save()});root.addEventListener('input',e=>{if(e.target.hasAttribute('data-ea-search')){state.lessonSearch=e.target.value;const pos=e.target.selectionStart;render();const input=$('[data-ea-search]',root);input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.dataset.eaNote){state.notes[e.target.dataset.eaNote]=e.target.value;save();if(e.target.dataset.eaNote.startsWith('writing:')){const n=$('[data-ea-wordcount]',root);if(n)n.textContent=window.SERAG_WRITING_V13.count(e.target.value)}}});return true}
  function disablePaid(){document.querySelectorAll('[data-speaking-feedback],[data-grammar-ai],[data-grammar-check-writing],[data-video-explain]').forEach(b=>{b.disabled=true;b.title='Disabled to avoid paid API usage';b.textContent='Paid AI — disabled'})}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-ea-external-topic]');if(b&&root){state.practiceTopic=b.dataset.eaExternalTopic;selected=null;save();start('topic');root.scrollIntoView({block:'start',behavior:'smooth'})}});
  const timer=setInterval(()=>{if(mount()){organizeLegacy();disablePaid();if(owner!==uid()){stop();load();render()} }},1200);window.addEventListener('pagehide',()=>{stop();if(audioUrl)URL.revokeObjectURL(audioUrl);clearInterval(timer)});
  function homeState(){if(!state||owner!==uid())load();return state}
  function homeQuestion(){homeState();const pool=questions().filter(q=>q.options.length<=3&&(q.level||lesson(q.topic)?.level)===state.level);return selectQuestions(pool,'daily',1)[0]||pool[0]||questions()[0]}
  function homeAnswer(id,answer){homeState();const q=questions().find(x=>x.id===id);if(!q||!q.options.includes(answer))return null;record(q,answer);return {correct:answer===q.answer,answer:q.answer,explanation:q.explanation}}
  function openFromHome(section='today',kind=null){if(!mount())return false;homeState();stop();if(section!=='play'&&session?.kind==='engoplay')session=null;tab=section;selected=null;render();if(kind)start(kind);return true}
  function setLevel(value){if(!['B1','B2','C1','C2'].includes(value))return;homeState();state.level=value;save()}
  function playSet(ids,size,title,level){if(!mount())return false;homeState();stop();setLevel(level);selected=null;const allowed=new Set(ids),pool=questions().filter(q=>allowed.has(q.id)),limit=[5,8,12].includes(size)?size:5,list=selectQuestions(pool,'daily',limit);session={kind:'engoplay',title,list:list.slice(0,limit),index:0,score:0,answered:false,answers:{},completed:false};tab='today';render();$('.ea14-questions',root)?.scrollIntoView({block:'nearest',behavior:'smooth'});return true}
  window.SERAG_ACADEMY_V12={lessons,setLevel,playSet,refreshPlay(){if(root&&tab==='play')render()},maps,scenarios,questions,selectQuestions,practicePool,topicId,homeState,homeQuestion,homeAnswer,open:openFromHome};
})();
